 cs_th::cs_th(const char *name, const char *title, 
                        RooAbsReal& _th,
                       // RooAbsReal& _L,
                        RooAbsReal& _Sigtot,
                        RooAbsReal& _B,
                        RooAbsReal& _Rho,
			double _Plab) :
   RooAbsPdf(name,title), 
   th("th","th",this,_th),
  // L("L","L",this,_L),
   Sigtot("Sigtot","Sigtot",this,_Sigtot),
   B("B","B",this,_B),
   Rho("Rho","Rho",this,_Rho),
   Plab(_Plab)
 { 
   M=0.938;
   //Plab=1.5;
   Elab=sqrt(M*M+Plab*Plab);
   S=2*M*M+2*M*Elab;
   pcm2=S/4.-M*M;
   gamma=(Elab+M)/sqrt(S);
   beta=Plab/Elab;
   lnP=log(Plab);
   pi=3.14159;
   hbarc2=0.389379;
   alpha=1./137.036;
   pkoef=10./(5.0677*5.0677);
   dt=1.0802e-5;
 } 


